-- TOC entry 261 (class 1255 OID 24712)
-- Name: actualizar_estado_credito(); Type: FUNCTION; Schema: public; Owner: lender
--

CREATE FUNCTION public.actualizar_estado_credito() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_credito_id INTEGER;
    v_total_pagado NUMERIC := 0;
    v_total_proyectado NUMERIC := 0;
BEGIN
    -- Determinar el credito_id afectado (depende del tipo de evento)
    IF (TG_OP = 'DELETE') THEN
        v_credito_id := OLD.credito_id;
    ELSE
        v_credito_id := NEW.credito_id;
    END IF;
    
    --⃣ Calcular el total pagado actual para ese crédito
    SELECT COALESCE(SUM(monto), 0)
    INTO v_total_pagado
    FROM pago
    WHERE credito_id = v_credito_id;

   --⃣ Obtener el total proyectado del crédito
    SELECT total_credito_proyectado
    INTO v_total_proyectado
    FROM credito
    WHERE credito_id = v_credito_id;

    --⃣ Actualizar el campo cancelado según corresponda
    UPDATE credito
    SET cancelado = CASE 
                        WHEN v_total_pagado >= v_total_proyectado THEN 1
                        ELSE 0
                    END
    WHERE credito_id = v_credito_id;

    RETURN NULL; -- No modificamos la fila del pago
END;
$$;


ALTER FUNCTION public.actualizar_estado_credito() OWNER TO lender;

--
-- TOC entry 248 (class 1255 OID 16390)
-- Name: auto_pago_id(); Type: FUNCTION; Schema: public; Owner: lender
--

CREATE FUNCTION public.auto_pago_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Si no se proporciona un pago_id, calculamos el siguiente
    IF NEW.pago_id IS NULL THEN
        SELECT COALESCE(MAX(pago_id), 0) + 1 INTO NEW.pago_id
        FROM public.pago
        WHERE credito_id = NEW.credito_id;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.auto_pago_id() OWNER TO lender;

