--
-- TOC entry 226 (class 1259 OID 16419)
-- Name: estado; Type: VIEW; Schema: public; Owner: lender
--

CREATE VIEW public.estado AS
 SELECT a.credito_id,
    (((b.nombres)::text || ' '::text) || (b.apellidos)::text) AS cliente,
    a.fecha AS fecha_credito,
    a.monto_colocado AS monto_otorgado,
    a.total_credito_proyectado,
    c.pagado AS total_pagado,
    c.ultima_fecha_pago,
    (a.total_credito_proyectado - c.pagado) AS saldo,
    (CURRENT_DATE - c.ultima_fecha_pago) AS dias_desde_pago,
        CASE
            WHEN (((CURRENT_DATE - c.ultima_fecha_pago) <= 30) OR (c.ultima_fecha_pago IS NULL)) THEN 'Al día'::text
            WHEN (((CURRENT_DATE - c.ultima_fecha_pago) > 30) AND ((CURRENT_DATE - c.ultima_fecha_pago) <= 60)) THEN '30 días'::text
            WHEN (((CURRENT_DATE - c.ultima_fecha_pago) > 60) AND ((CURRENT_DATE - c.ultima_fecha_pago) <= 90)) THEN '60 días'::text
            WHEN (((CURRENT_DATE - c.ultima_fecha_pago) > 90) AND ((CURRENT_DATE - c.ultima_fecha_pago) <= 120)) THEN '90 días'::text
            ELSE 'Mas de 90 días'::text
        END AS "case"
   FROM ((public.credito a
     LEFT JOIN public.persona b ON ((a.persona_id = b.persona_id)))
     LEFT JOIN ( SELECT pago.credito_id,
            sum(pago.monto) AS pagado,
            max(pago.fecha) AS ultima_fecha_pago
           FROM public.pago
          GROUP BY pago.credito_id) c ON ((a.credito_id = c.credito_id)))
  WHERE ((a.cancelado = 0) AND (a.privado = 0))
  ORDER BY (CURRENT_DATE - c.ultima_fecha_pago) DESC;


ALTER VIEW public.estado OWNER TO lender;

