CREATE VIEW public.saldos AS
 SELECT b.persona_id,
    a.credito_id,
    b.nombres,
    b.apellidos,
    b.direccion,
    a.fecha AS fecha_credito,
    a.monto_colocado AS monto_otorgado,
    a.total_credito_proyectado,
    a.cuota,
    a.dia_pago,
    a.numero_cuotas,
    a.privado,
    COALESCE(c.pagado, (0)::numeric) AS total_pagado,
    LEAST((EXTRACT(month FROM age((CURRENT_DATE)::timestamp with time zone, (a.fecha)::timestamp with time zone)) * a.cuota), a.total_credito_proyectado) AS pagos_debio,
    trunc(((LEAST((EXTRACT(month FROM age((CURRENT_DATE)::timestamp with time zone, (a.fecha)::timestamp with time zone)) * a.cuota), a.total_credito_proyectado) - COALESCE(c.pagado, (0)::numeric)) / a.cuota)) AS meses_pendientes,
    (trunc((((EXTRACT(month FROM age((CURRENT_DATE)::timestamp with time zone, (a.fecha)::timestamp with time zone)) * a.cuota) - COALESCE(c.pagado, (0)::numeric)) / a.cuota)) * (20)::numeric) AS total_multa,
    (LEAST((EXTRACT(month FROM age((CURRENT_DATE)::timestamp with time zone, (a.fecha)::timestamp with time zone)) * a.cuota), a.total_credito_proyectado) - COALESCE(c.pagado, (0)::numeric)) AS saldo_poner_al_dia,
    ((LEAST((EXTRACT(month FROM age((CURRENT_DATE)::timestamp with time zone, (a.fecha)::timestamp with time zone)) * a.cuota), a.total_credito_proyectado) - COALESCE(c.pagado, (0)::numeric)) + (trunc((((EXTRACT(month FROM age((CURRENT_DATE)::timestamp with time zone, (a.fecha)::timestamp with time zone)) * a.cuota) - COALESCE(c.pagado, (0)::numeric)) / a.cuota)) * (20)::numeric)) AS saldo_poner_al_dia_mas_multa,
    (a.total_credito_proyectado - COALESCE(c.pagado, (0)::numeric)) AS saldo_total,
        CASE
            WHEN (trunc((((EXTRACT(month FROM age((CURRENT_DATE)::timestamp with time zone, (a.fecha)::timestamp with time zone)) * a.cuota) - COALESCE(c.pagado, (0)::numeric)) / a.cuota)) <= (0)::numeric) THEN 'Al día'::text
            WHEN (trunc((((EXTRACT(month FROM age((CURRENT_DATE)::timestamp with time zone, (a.fecha)::timestamp with time zone)) * a.cuota) - COALESCE(c.pagado, (0)::numeric)) / a.cuota)) = (1)::numeric) THEN '30 días'::text
            WHEN (trunc((((EXTRACT(month FROM age((CURRENT_DATE)::timestamp with time zone, (a.fecha)::timestamp with time zone)) * a.cuota) - COALESCE(c.pagado, (0)::numeric)) / a.cuota)) = (2)::numeric) THEN '60 días'::text
            WHEN (trunc((((EXTRACT(month FROM age((CURRENT_DATE)::timestamp with time zone, (a.fecha)::timestamp with time zone)) * a.cuota) - COALESCE(c.pagado, (0)::numeric)) / a.cuota)) <= (3)::numeric) THEN '90 días'::text
            ELSE 'Mas de 90 días'::text
        END AS nivel_mora,
        CASE
            WHEN (a.estado_juridico = 1) THEN 'Juridico'::text
            ELSE NULL::text
        END AS juridico
   FROM ((public.credito a
     LEFT JOIN public.persona b ON ((a.persona_id = b.persona_id)))
     LEFT JOIN ( SELECT pago.credito_id,
