            count(1) AS numero_pagos
           FROM public.pago
          GROUP BY pago.credito_id) c ON ((a.credito_id = c.credito_id)))
  WHERE ((a.cancelado = 0) AND (b.persona_id = 25))
  ORDER BY a.credito_id DESC;


